"use client";

import React, { useEffect, useRef } from "react";
import { initRiskProfiling } from "./riskProfilingLogic";

const STYLES_CSS = ":root{\n        --bg:#F5F8F5;\n        --surface:#FFFFFF;\n        --ink:#152420;\n        --muted:#5C6B63;\n        --faint:#84938A;\n        --line:#DEE7E0;\n        --line-strong:#C9D6CC;\n        --primary:#0C6B4F;\n        --primary-dark:#084F3A;\n        --primary-soft:#E7F3EC;\n        --amber-bg:#FFF6DF;\n        --amber-line:#EDD48A;\n        --amber-ink:#7A5A05;\n        --c-cons:#2F6DB3;\n        --c-cons-soft:#EAF2FB;\n        --c-mod:#0C6B4F;\n        --c-mod-soft:#E7F3EC;\n        --c-agg:#C2500F;\n        --c-agg-soft:#FDF0E7;\n        --a-equity:#178A50;\n        --a-debt:#2F6DB3;\n        --a-gold:#DFA00C;\n        --a-liquid:#93A1B0;\n        --radius:18px;\n        --shadow:0 1px 2px rgba(21,36,32,.05),0 8px 24px rgba(21,36,32,.06);\n        --shadow-lift:0 2px 4px rgba(21,36,32,.06),0 16px 36px rgba(21,36,32,.12);\n      }\n      *{box-sizing:border-box;-webkit-tap-highlight-color:transparent;}\n      html{scroll-behavior:smooth;}\n      body{\n        margin:0;background:var(--bg);color:var(--ink);\n        font-family:var(--font-google-sans), sans-serif;\n        font-size:16px;line-height:1.45;\n      }\n      .wrap{max-width:980px;margin:0 auto;padding:20px 16px 56px;}\n\n      /* ---------- Progress ---------- */\n      .progress-row{display:flex;align-items:center;gap:12px;margin:6px 2px 18px;}\n      .progress-label{font-size:13px;font-weight:700;color:var(--muted);white-space:nowrap;letter-spacing:.02em;}\n      .progress-track{flex:1;height:8px;border-radius:99px;background:#E3EBE4;overflow:hidden;}\n      .progress-fill{height:100%;width:50%;border-radius:99px;background:var(--primary);transition:width .6s cubic-bezier(.22,1,.36,1);}\n\n      /* ---------- Steps ---------- */\n      .step{display:none;}\n      .step.active{display:block;animation:stepIn .45s cubic-bezier(.22,1,.36,1) both;}\n      .step.leaving{animation:stepOut .22s ease both;}\n      @keyframes stepIn{from{opacity:0;transform:translateX(26px);}to{opacity:1;transform:none;}}\n      @keyframes stepInBack{from{opacity:0;transform:translateX(-26px);}to{opacity:1;transform:none;}}\n      @keyframes stepOut{from{opacity:1;}to{opacity:0;transform:translateX(-14px);}}\n      .step.active.back{animation:stepInBack .45s cubic-bezier(.22,1,.36,1) both;}\n\n      h1{font-size:clamp(26px,4.6vw,38px);line-height:1.15;margin:0 0 8px;font-weight:800;letter-spacing:-.01em;}\n      h2{font-size:clamp(20px,3.4vw,26px);margin:0 0 6px;font-weight:800;letter-spacing:-.01em;}\n      .sub{color:var(--muted);margin:0 0 22px;font-size:15.5px;}\n      .section-label{font-size:13px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--faint);margin:0 0 10px;}\n\n      /* ---------- Style cards (Step 1) ---------- */\n      .style-grid{display:grid;grid-template-columns:1fr;gap:14px;}\n      @media(min-width:760px){.style-grid{grid-template-columns:repeat(3,1fr);}}\n      .style-card{\n        position:relative;text-align:left;width:100%;cursor:pointer;\n        background:var(--surface);border:2px solid var(--line);border-radius:var(--radius);\n        padding:22px 20px 18px;box-shadow:var(--shadow);\n        transition:transform .25s ease,box-shadow .25s ease,border-color .25s ease;\n        font-family:inherit;color:var(--ink);\n      }\n      .style-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-lift);}\n      .style-card:active{transform:translateY(-1px) scale(.99);}\n      .style-card .icon-badge{\n        width:52px;height:52px;border-radius:14px;display:grid;place-items:center;margin-bottom:14px;\n      }\n      .style-card[data-style=\"conservative\"] .icon-badge{background:var(--c-cons-soft);color:var(--c-cons);}\n      .style-card[data-style=\"moderate\"] .icon-badge{background:var(--c-mod-soft);color:var(--c-mod);}\n      .style-card[data-style=\"aggressive\"] .icon-badge{background:var(--c-agg-soft);color:var(--c-agg);}\n      .style-card h3{margin:0 0 4px;font-size:21px;font-weight:800;}\n      .style-card .tagline{margin:0 0 16px;color:var(--muted);font-size:14.5px;min-height:42px;}\n      .style-card.selected{border-color:var(--primary);}\n      .style-card[data-style=\"conservative\"].selected{border-color:var(--c-cons);}\n      .style-card[data-style=\"aggressive\"].selected{border-color:var(--c-agg);}\n      .tick{\n        position:absolute;top:16px;right:16px;width:28px;height:28px;border-radius:50%;\n        background:var(--primary);color:#fff;display:grid;place-items:center;\n        opacity:0;transform:scale(.4);transition:opacity .25s ease,transform .3s cubic-bezier(.34,1.56,.64,1);\n      }\n      .style-card[data-style=\"conservative\"] .tick{background:var(--c-cons);}\n      .style-card[data-style=\"aggressive\"] .tick{background:var(--c-agg);}\n      .style-card.selected .tick{opacity:1;transform:scale(1);}\n\n      /* split bar */\n      .split-bar{display:flex;height:14px;border-radius:99px;overflow:hidden;background:#EDF1ED;margin:0 0 8px;}\n      .split-bar span{display:block;height:100%;width:0;transition:width 1s cubic-bezier(.22,1,.36,1);}\n      .split-bar span.seg-equity{background:var(--a-equity);}\n      .split-bar span.seg-debt{background:var(--a-debt);}\n      .split-bar span.seg-gold{background:var(--a-gold);}\n      .split-bar span.seg-liquid{background:var(--a-liquid);}\n      .split-legend{display:flex;flex-wrap:wrap;gap:4px 12px;font-size:12px;color:var(--muted);margin-bottom:14px;}\n      .split-legend i{width:9px;height:9px;border-radius:3px;display:inline-block;margin-right:5px;font-style:normal;vertical-align:-1px;}\n      .fits{font-size:13.5px;color:var(--muted);border-top:1px solid var(--line);padding-top:12px;margin:0 0 12px;}\n      .fits strong{color:var(--ink);font-weight:700;}\n      .card-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;}\n      .return-label{font-size:13px;font-weight:700;color:var(--ink);}\n      .return-label small{display:block;font-weight:500;color:var(--faint);font-size:11.5px;}\n      .risk-dots{display:flex;gap:5px;align-items:center;}\n      .risk-dots i{width:10px;height:10px;border-radius:50%;background:#E1E9E2;}\n      .risk-dots i.on{background:var(--primary);}\n      [data-style=\"conservative\"] .risk-dots i.on{background:var(--c-cons);}\n      [data-style=\"aggressive\"] .risk-dots i.on{background:var(--c-agg);}\n      .risk-dots em{font-style:normal;font-size:11.5px;color:var(--faint);margin-left:4px;font-weight:600;}\n\n      /* ---------- Quiz ---------- */\n      .quiz-link-wrap{text-align:center;margin-top:26px;}\n      .quiz-link{\n        background:none;border:none;cursor:pointer;font-family:inherit;font-size:15px;font-weight:700;\n        color:var(--primary);text-decoration:underline;text-underline-offset:4px;padding:10px;\n      }\n      .quiz-panel{\n        margin-top:16px;background:var(--surface);border:1.5px solid var(--line);border-radius:var(--radius);\n        padding:22px;box-shadow:var(--shadow);display:none;\n      }\n      .quiz-panel.open{display:block;animation:stepIn .35s ease both;}\n      .quiz-q{margin-bottom:20px;}\n      .quiz-q:last-of-type{margin-bottom:6px;}\n      .quiz-q p{margin:0 0 10px;font-weight:700;font-size:15.5px;}\n      .quiz-q p span{color:var(--faint);font-weight:600;margin-right:6px;}\n      .quiz-opts{display:flex;flex-wrap:wrap;gap:8px;}\n      .quiz-opt{\n        flex:1 1 140px;cursor:pointer;font-family:inherit;font-size:14px;font-weight:600;color:var(--ink);\n        background:#F7FAF7;border:1.5px solid var(--line);border-radius:12px;padding:12px 10px;min-height:48px;\n        transition:border-color .2s,background .2s,transform .15s;\n      }\n      .quiz-opt:hover{border-color:var(--line-strong);}\n      .quiz-opt.picked{border-color:var(--primary);background:var(--primary-soft);}\n      .quiz-result{display:none;margin-top:14px;padding:14px 16px;border-radius:12px;background:var(--primary-soft);font-weight:700;font-size:15px;text-align:center;}\n      .quiz-result.show{display:block;animation:stepIn .3s ease both;}\n\n      /* ---------- Step 2 header ---------- */\n      .style-banner{\n        display:flex;flex-wrap:wrap;align-items:center;gap:12px;\n        background:var(--surface);border:1.5px solid var(--line);border-radius:var(--radius);\n        padding:14px 16px;box-shadow:var(--shadow);margin-bottom:14px;\n      }\n      .style-chip{display:inline-flex;align-items:center;gap:8px;font-weight:800;font-size:16px;}\n      .style-chip .dot{width:12px;height:12px;border-radius:50%;}\n      .btn{\n        cursor:pointer;font-family:inherit;font-weight:700;border-radius:12px;border:1.5px solid var(--line-strong);\n        background:var(--surface);color:var(--ink);padding:10px 16px;font-size:14px;min-height:44px;\n        transition:transform .15s,box-shadow .2s,background .2s,border-color .2s;\n      }\n      .btn:hover{box-shadow:var(--shadow);}\n      .btn:active{transform:scale(.97);}\n      .btn.primary{background:var(--primary);border-color:var(--primary);color:#fff;font-size:15px;padding:12px 22px;}\n      .btn.primary:hover{background:var(--primary-dark);}\n      .btn.ghost{border-color:transparent;color:var(--primary);}\n      .spacer{flex:1;}\n      .try-row{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:24px;}\n      .try-row span{font-size:13.5px;color:var(--muted);font-weight:600;}\n      .pill{\n        cursor:pointer;font-family:inherit;font-size:14px;font-weight:700;padding:9px 16px;min-height:42px;\n        border-radius:99px;border:1.5px solid var(--line-strong);background:var(--surface);color:var(--ink);\n        transition:all .2s;\n      }\n      .pill.on{background:var(--ink);color:#fff;border-color:var(--ink);}\n\n      /* ---------- Goal grid ---------- */\n      .goal-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-bottom:26px;}\n      @media(min-width:640px){.goal-grid{grid-template-columns:repeat(3,1fr);}}\n      @media(min-width:900px){.goal-grid{grid-template-columns:repeat(4,1fr);}}\n      .goal-card{\n        cursor:pointer;font-family:inherit;text-align:left;color:var(--ink);\n        background:var(--surface);border:2px solid var(--line);border-radius:16px;padding:16px 14px;min-height:104px;\n        display:flex;flex-direction:column;gap:8px;box-shadow:var(--shadow);\n        transition:transform .2s,border-color .2s,box-shadow .2s,background .2s;\n      }\n      .goal-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-lift);}\n      .goal-card:active{transform:scale(.98);}\n      .goal-card .g-icon{width:40px;height:40px;border-radius:11px;background:#EFF5F0;color:var(--primary);display:grid;place-items:center;}\n      .goal-card .g-name{font-weight:700;font-size:15px;line-height:1.25;}\n      .goal-card .g-meta{font-size:12.5px;color:var(--faint);font-weight:600;margin-top:auto;}\n      .goal-card.selected{border-color:var(--primary);background:var(--primary-soft);}\n      .goal-card.selected .g-icon{background:#fff;}\n\n      /* ---------- Cards / panels ---------- */\n      .panel{\n        background:var(--surface);border:1.5px solid var(--line);border-radius:var(--radius);\n        padding:22px;box-shadow:var(--shadow);margin-bottom:18px;\n      }\n      .panel h2{margin-bottom:4px;}\n      .panel .sub{margin-bottom:18px;}\n\n      /* calculator */\n      .calc-grid{display:grid;grid-template-columns:1fr;gap:26px;}\n      @media(min-width:820px){.calc-grid{grid-template-columns:1.1fr .9fr;}}\n      .field{margin-bottom:22px;}\n      .field:last-child{margin-bottom:0;}\n      .field-head{display:flex;justify-content:space-between;align-items:baseline;gap:10px;margin-bottom:10px;}\n      .field-head label{font-weight:700;font-size:15px;}\n      .amount-input{\n        display:inline-flex;align-items:center;gap:2px;border:1.5px solid var(--line-strong);border-radius:10px;\n        padding:6px 10px;background:#FBFCFB;font-weight:800;font-size:16px;\n      }\n      .amount-input input{\n        border:none;background:none;font:inherit;color:var(--ink);width:110px;text-align:right;outline:none;padding:0;\n      }\n      .amount-input input:focus{color:var(--primary);}\n      input[type=range]{\n        -webkit-appearance:none;appearance:none;width:100%;height:8px;border-radius:99px;background:#E3EBE4;outline:none;cursor:pointer;\n      }\n      input[type=range]::-webkit-slider-thumb{\n        -webkit-appearance:none;width:28px;height:28px;border-radius:50%;background:var(--primary);\n        border:3px solid #fff;box-shadow:0 2px 8px rgba(12,107,79,.4);cursor:grab;\n      }\n      input[type=range]::-moz-range-thumb{\n        width:24px;height:24px;border-radius:50%;background:var(--primary);border:3px solid #fff;\n        box-shadow:0 2px 8px rgba(12,107,79,.4);cursor:grab;\n      }\n      .range-marks{display:flex;justify-content:space-between;font-size:11.5px;color:var(--faint);font-weight:600;margin-top:6px;}\n      .assumption{font-size:13px;color:var(--muted);background:#F7FAF7;border:1px dashed var(--line-strong);border-radius:10px;padding:10px 12px;}\n      .assumption strong{color:var(--ink);}\n\n      .results{display:flex;flex-direction:column;gap:0;}\n      .sip-hero{padding-bottom:16px;border-bottom:1px solid var(--line);margin-bottom:14px;}\n      .sip-hero .k{font-size:13px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--faint);}\n      .sip-hero .v{font-size:clamp(38px,6vw,50px);font-weight:800;letter-spacing:-.02em;line-height:1.1;color:var(--primary-dark);}\n      .sip-hero .v small{font-size:17px;font-weight:700;color:var(--muted);}\n      .result-row{display:flex;justify-content:space-between;align-items:baseline;padding:8px 0;font-size:15px;}\n      .result-row .k{color:var(--muted);font-weight:600;}\n      .result-row .v{font-weight:800;}\n      .result-row.alt{border-top:1px dashed var(--line);margin-top:6px;padding-top:14px;}\n\n      /* guardrail */\n      .guardrail{\n        display:none;align-items:flex-start;gap:12px;background:var(--amber-bg);border:1.5px solid var(--amber-line);\n        border-radius:14px;padding:14px 16px;margin-bottom:18px;font-size:14.5px;color:var(--amber-ink);\n      }\n      .guardrail.show{display:flex;animation:stepIn .35s ease both;}\n      .guardrail p{margin:0;flex:1;font-weight:600;}\n      .guardrail .btn{border-color:var(--amber-line);background:#fff;color:var(--amber-ink);white-space:nowrap;min-height:40px;padding:8px 14px;}\n\n      /* allocation */\n      .alloc-grid{display:grid;grid-template-columns:1fr;gap:22px;align-items:center;}\n      @media(min-width:640px){.alloc-grid{grid-template-columns:220px 1fr;}}\n      .donut-wrap{position:relative;width:210px;height:210px;margin:0 auto;}\n      .donut-wrap svg{transform:rotate(-90deg);}\n      .donut-seg{transition:stroke-dasharray .9s cubic-bezier(.22,1,.36,1),stroke-dashoffset .9s cubic-bezier(.22,1,.36,1);}\n      .donut-center{position:absolute;inset:0;display:grid;place-content:center;text-align:center;pointer-events:none;}\n      .donut-center .big{font-size:30px;font-weight:800;line-height:1;}\n      .donut-center .small{font-size:12.5px;color:var(--muted);font-weight:600;margin-top:4px;}\n      .legend{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px;}\n      .legend li{display:flex;align-items:center;gap:10px;font-size:15px;}\n      .legend i{width:14px;height:14px;border-radius:4px;flex:none;}\n      .legend .nm{font-weight:600;flex:1;}\n      .legend .pc{font-weight:800;}\n\n      /* fund categories */\n      .fund-row{\n        display:flex;gap:14px;align-items:flex-start;padding:15px 0;border-bottom:1px solid var(--line);\n      }\n      .fund-row:last-child{border-bottom:none;padding-bottom:2px;}\n      .fund-row:first-of-type{padding-top:6px;}\n      .fund-main{flex:1;min-width:0;}\n      .fund-name{font-weight:800;font-size:16px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;}\n      .pick-tag{\n        font-size:11px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;\n        background:var(--primary);color:#fff;border-radius:99px;padding:3px 9px;\n      }\n      .fund-desc{color:var(--muted);font-size:13.5px;margin-top:2px;}\n      .fund-amt{text-align:right;flex:none;}\n      .fund-amt .pc{font-weight:800;font-size:16px;}\n      .fund-amt .rs{color:var(--primary-dark);font-weight:700;font-size:14px;display:block;}\n      .fund-bar{height:6px;border-radius:99px;background:#EDF1ED;margin-top:10px;overflow:hidden;}\n      .fund-bar span{display:block;height:100%;background:var(--primary);border-radius:99px;transition:width .8s cubic-bezier(.22,1,.36,1);}\n\n      /* protection checks */\n      .protect-grid{display:grid;grid-template-columns:1fr;gap:12px;}\n      @media(min-width:760px){.protect-grid{grid-template-columns:repeat(3,1fr);}}\n      .protect-card{border:1.5px solid var(--line);border-radius:14px;padding:16px;background:#FBFCFB;}\n      .protect-card h3{margin:0 0 4px;font-size:15.5px;font-weight:800;display:flex;gap:8px;align-items:center;}\n      .protect-card h3 svg{color:var(--primary);flex:none;}\n      .protect-card .q{color:var(--muted);font-size:13.5px;margin:0 0 12px;}\n      .yn{display:flex;gap:8px;}\n      .yn button{\n        flex:1;cursor:pointer;font-family:inherit;font-weight:700;font-size:14px;min-height:44px;\n        border-radius:10px;border:1.5px solid var(--line-strong);background:#fff;color:var(--ink);transition:all .2s;\n      }\n      .yn button.on-yes{background:var(--primary-soft);border-color:var(--primary);color:var(--primary-dark);}\n      .yn button.on-no{background:var(--amber-bg);border-color:var(--amber-line);color:var(--amber-ink);}\n      .gap-note{display:none;margin:12px 0 0;font-size:13px;font-weight:600;color:var(--amber-ink);background:var(--amber-bg);border-radius:8px;padding:8px 10px;}\n      .gap-note.show{display:block;animation:stepIn .3s ease both;}\n\n      /* summary */\n      .summary-card{\n        background:var(--primary-soft);border:1.5px solid #BFE0CF;border-radius:var(--radius);padding:22px;margin-bottom:18px;\n        transition:box-shadow .3s;\n      }\n      .summary-card.pulse{box-shadow:0 0 0 4px rgba(12,107,79,.35),var(--shadow-lift);}\n      .summary-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px 18px;margin-top:14px;}\n      @media(min-width:640px){.summary-grid{grid-template-columns:repeat(5,1fr);}}\n      .summary-grid .k{font-size:12px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;color:var(--faint);}\n      .summary-grid .v{font-weight:800;font-size:16.5px;margin-top:2px;}\n      .cta-row{display:flex;flex-wrap:wrap;gap:12px;align-items:center;}\n      .disclaimer{font-size:12.5px;color:var(--faint);text-align:center;margin:22px auto 0;max-width:560px;}\n\n      /* FH list funds */\n      .fund-meta{font-size:12.5px;color:var(--faint);font-weight:700;margin-top:3px;letter-spacing:.01em;}\n      .fund-meta b{color:var(--muted);font-weight:800;}\n      .fund-actions{display:flex;flex-wrap:wrap;gap:8px 14px;margin-top:10px;align-items:center;}\n      .link-btn{background:none;border:none;cursor:pointer;font-family:inherit;font-size:13px;font-weight:800;color:var(--primary);padding:4px 2px;text-decoration:underline;text-underline-offset:3px;}\n      .link-btn.secondary{color:var(--muted);font-weight:700;}\n      .see-all{display:none;margin-top:10px;background:#F7FAF7;border:1px solid var(--line);border-radius:10px;padding:10px 12px;}\n      .see-all.open{display:block;animation:stepIn .25s ease both;}\n      .see-all h4{margin:0 0 8px;font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:var(--faint);}\n      .see-all ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:7px;}\n      .see-all li{display:flex;justify-content:space-between;gap:12px;font-size:13.5px;}\n      .see-all li span:first-child{font-weight:700;}\n      .see-all li span:last-child{color:var(--faint);font-weight:700;white-space:nowrap;}\n      .list-note{font-size:12.5px;color:var(--faint);line-height:1.5;margin-top:14px;border-top:1px dashed var(--line);padding-top:12px;}\n\n      /* Action panel inside summary */\n      .report-actions{margin-top:20px;border-top:1px solid #BFE0CF;padding-top:18px;}\n      .report-actions label{font-size:13px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;color:var(--muted);display:block;margin-bottom:8px;}\n      .name-input{width:100%;max-width:420px;font-family:inherit;font-size:15px;font-weight:600;padding:12px 14px;border:1.5px solid var(--line-strong);border-radius:12px;background:#fff;color:var(--ink);outline:none;}\n      .name-input:focus{border-color:var(--primary);}\n      .action-btns{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px;}\n      .btn.ai-btn{background:#152420;border-color:#152420;color:#fff;}\n      .btn.ai-btn:hover{background:#000;}\n      .btn.pdf-btn{background:var(--primary);border-color:var(--primary);color:#fff;}\n\n      /* AI Modal */\n      .modal-overlay{display:none;position:fixed;inset:0;background:rgba(21,36,32,.55);z-index:50;align-items:flex-end;justify-content:center;padding:0;}\n      @media(min-width:640px){.modal-overlay{align-items:center;padding:20px;}}\n      .modal-overlay.open{display:flex;}\n      .modal-card{background:#fff;width:100%;max-width:680px;max-height:92vh;overflow:auto;border-radius:20px 20px 0 0;padding:24px 22px 28px;box-shadow:0 20px 50px rgba(0,0,0,.25);}\n      @media(min-width:640px){.modal-card{border-radius:20px;}}\n      .modal-head{display:flex;align-items:flex-start;gap:12px;margin-bottom:6px;}\n      .modal-head h3{margin:0;font-size:21px;line-height:1.2;}\n      .badge{font-size:11px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;background:#FFF6DF;border:1px solid #EDD48A;color:#7A5A05;border-radius:99px;padding:4px 9px;white-space:nowrap;margin-top:2px;}\n      .modal-close{margin-left:auto;background:#F1F5F1;border:none;width:38px;height:38px;border-radius:50%;cursor:pointer;font-size:18px;line-height:1;flex:none;}\n      .modal-sub{color:var(--muted);font-size:13.5px;margin:0 0 16px;}\n      .shimmer-wrap{padding:10px 0 4px;}\n      .shimmer-line{height:14px;border-radius:99px;background:linear-gradient(90deg,#EDF1ED 25%,#F7FAF7 50%,#EDF1ED 75%);background-size:200% 100%;animation:shimmer 1.1s infinite;margin-bottom:10px;}\n      @keyframes shimmer{to{background-position:-200% 0;}}\n      .ai-body{font-size:15px;line-height:1.65;color:#24312B;}\n      .ai-body h4{margin:18px 0 6px;font-size:15px;color:var(--ink);}\n      .ai-body h4:first-child{margin-top:2px;}\n      .ai-body p{margin:0 0 10px;}\n      .ai-body ul{margin:0 0 10px;padding-left:18px;}\n      .ai-body li{margin-bottom:6px;}\n      .ai-foot{margin-top:18px;border-top:1px solid var(--line);padding-top:12px;font-size:12.5px;color:var(--faint);line-height:1.5;}\n\n      /* ---------- PMS section ---------- */\n      .pms-strip{background:var(--amber-bg);border:1.5px solid var(--amber-line);color:var(--amber-ink);border-radius:10px;padding:10px 12px;font-size:13px;font-weight:700;margin-bottom:18px;line-height:1.5;}\n      .pms-amt-row{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-bottom:10px;}\n      .pms-chips{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:18px;}\n      .pms-chip{cursor:pointer;font-family:inherit;font-size:13.5px;font-weight:700;padding:9px 14px;min-height:42px;border-radius:99px;border:1.5px solid var(--line-strong);background:var(--surface);color:var(--ink);transition:all .2s;}\n      .pms-chip.on{background:var(--ink);color:#fff;border-color:var(--ink);}\n      .route-grid{display:grid;grid-template-columns:1fr;gap:10px;margin-bottom:6px;}\n      @media(min-width:760px){.route-grid{grid-template-columns:repeat(3,1fr);}}\n      .route-card{position:relative;text-align:left;width:100%;cursor:pointer;background:var(--surface);border:2px solid var(--line);border-radius:14px;padding:16px 14px;font-family:inherit;color:var(--ink);transition:transform .2s,border-color .2s,box-shadow .2s,opacity .2s;box-shadow:var(--shadow);}\n      .route-card:hover{transform:translateY(-2px);box-shadow:var(--shadow-lift);}\n      .route-card.selected{border-color:var(--primary);background:var(--primary-soft);}\n      .route-card.disabled{opacity:.48;cursor:not-allowed;box-shadow:none;}\n      .route-card.disabled:hover{transform:none;box-shadow:none;}\n      .route-card h3{margin:0 0 4px;font-size:15.5px;font-weight:800;padding-right:26px;}\n      .route-card p{margin:0;color:var(--muted);font-size:13.5px;line-height:1.45;}\n      .route-tick{position:absolute;top:12px;right:12px;width:24px;height:24px;border-radius:50%;background:var(--primary);color:#fff;display:grid;place-items:center;opacity:0;transform:scale(.4);transition:opacity .25s,transform .3s cubic-bezier(.34,1.56,.64,1);}\n      .route-card.selected .route-tick{opacity:1;transform:scale(1);}\n      .pms-note-amber{display:none;background:var(--amber-bg);border:1.5px solid var(--amber-line);color:var(--amber-ink);border-radius:10px;padding:12px 14px;font-size:13.5px;font-weight:600;line-height:1.55;margin-top:12px;}\n      .pms-note-amber.show{display:block;animation:stepIn .3s ease both;}\n      .pms-note-red{display:none;background:#FDF0E7;border:1.5px solid #E8A87C;color:#7A2E05;border-radius:10px;padding:12px 14px;font-size:13.5px;font-weight:700;line-height:1.55;margin-top:12px;}\n      .pms-note-red.show{display:block;animation:stepIn .3s ease both;}\n      .mix-panel{display:none;margin-top:18px;border-top:1px dashed var(--line-strong);padding-top:18px;}\n      .mix-panel.open{display:block;animation:stepIn .35s ease both;}\n      .mix-explain{font-size:14.5px;font-weight:600;background:#F7FAF7;border:1px solid var(--line);border-radius:10px;padding:12px 14px;margin:0 0 18px;line-height:1.55;}\n      .mix-slider-head{display:flex;justify-content:space-between;gap:10px;font-size:14px;font-weight:800;margin-bottom:8px;flex-wrap:wrap;}\n      .mix-outputs{display:grid;grid-template-columns:1fr;gap:10px;margin:16px 0;}\n      @media(min-width:640px){.mix-outputs{grid-template-columns:repeat(3,1fr);}}\n      .mix-out{border:1.5px solid var(--line);border-radius:12px;padding:14px;background:#FBFCFB;}\n      .mix-out .k{font-size:11.5px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;color:var(--faint);}\n      .mix-out .v{font-size:21px;font-weight:800;margin-top:3px;}\n      .mix-out.pms-out{border-color:#BFE0CF;background:var(--primary-soft);}\n      .strat-row{display:flex;gap:14px;align-items:flex-start;padding:13px 0;border-bottom:1px solid var(--line);}\n      .strat-row:last-child{border-bottom:none;}\n      .pms-only-panel{display:none;margin-top:16px;background:#F7FAF7;border:1.5px solid var(--line-strong);border-radius:12px;padding:16px;}\n      .pms-only-panel.open{display:block;animation:stepIn .3s ease both;}\n      .pms-only-panel p{margin:0 0 12px;font-size:14.5px;line-height:1.55;}\n      .disclosures{border:1.5px solid var(--line);border-radius:var(--radius);background:var(--surface);padding:20px 22px;margin-bottom:18px;box-shadow:var(--shadow);}\n      .disclosures h2{font-size:17px;margin-bottom:10px;}\n      .disclosures p{font-size:12.5px;color:var(--muted);line-height:1.6;margin:0 0 10px;}\n      .disclosures p:last-child{margin-bottom:0;}\n      .disclosures p strong{color:var(--ink);}\n      .summary-route{margin-top:14px;border-top:1px solid #BFE0CF;padding-top:12px;font-size:14.5px;font-weight:600;line-height:1.55;}\n      .summary-route .k{font-size:12px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;color:var(--faint);display:block;margin-bottom:2px;}\n      .summary-route .invalid{color:#B34700;font-weight:800;}\n\n      /* PMS strategy rows, returns, drawer */\n      .strat-row{border:2px solid transparent;border-radius:14px;padding:13px 12px;margin:0 -6px 4px;cursor:pointer;transition:background .2s,border-color .2s;}\n      .strat-row:hover{background:#F7FAF7;}\n      .strat-row.sel{border-color:var(--primary);background:var(--primary-soft);}\n      .radio-dot{width:20px;height:20px;border-radius:50%;border:2px solid var(--line-strong);flex:none;margin-top:3px;display:grid;place-items:center;background:#fff;transition:all .2s;}\n      .radio-dot::after{content:\"\";width:10px;height:10px;border-radius:50%;background:var(--primary);transform:scale(0);transition:transform .25s cubic-bezier(.34,1.56,.64,1);}\n      .strat-row.sel .radio-dot{border-color:var(--primary);}\n      .strat-row.sel .radio-dot::after{transform:scale(1);}\n      .mini-rets{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px;}\n      .mini-ret{background:#F7FAF7;border:1px solid var(--line);border-radius:8px;padding:5px 9px;font-size:11.5px;font-weight:700;color:var(--muted);white-space:nowrap;}\n      .strat-row.sel .mini-ret{background:#fff;}\n      .mini-ret b{font-size:12.5px;margin-left:3px;}\n      .pos{color:var(--primary-dark);} .neg{color:#B34700;}\n      .tap-hint{font-size:12px;color:var(--faint);font-weight:700;text-align:right;}\n      .split-wrap{display:none;margin-top:16px;background:#F7FAF7;border:1px solid var(--line);border-radius:12px;padding:14px;}\n      .split-wrap.open{display:block;animation:stepIn .3s ease both;}\n      .pms-card{max-width:780px;}\n      .ret-strip{display:grid;grid-template-columns:repeat(auto-fit,minmax(88px,1fr));gap:8px;margin-bottom:16px;}\n      .ret-box{border:1.5px solid var(--line);border-radius:12px;padding:10px 6px;text-align:center;background:#FBFCFB;}\n      .ret-box .k{font-size:10.5px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;color:var(--faint);line-height:1.3;min-height:27px;}\n      .ret-box .v{font-size:16.5px;font-weight:800;margin-top:2px;}\n      .ret-box .b{font-size:11px;color:var(--muted);font-weight:600;margin-top:1px;}\n      .drawer-sec{margin-bottom:18px;}\n      .drawer-sec h4{margin:0 0 8px;font-size:14.5px;font-weight:800;}\n      .chart-wrap{border:1.5px solid var(--line);border-radius:12px;padding:14px 12px 8px;background:#fff;}\n      .chart-legend{display:flex;gap:16px;font-size:12px;font-weight:700;color:var(--muted);margin-bottom:8px;flex-wrap:wrap;}\n      .chart-legend i{width:11px;height:11px;border-radius:3px;display:inline-block;margin-right:5px;vertical-align:-1px;}\n      .cb{transition:transform .8s cubic-bezier(.22,1,.36,1);}\n      .dgrid{display:grid;grid-template-columns:1fr 1fr;gap:9px;}\n      @media(min-width:640px){.dgrid{grid-template-columns:repeat(3,1fr);}}\n      .dbox{border:1.5px solid var(--line);border-radius:12px;padding:11px 12px;background:#FBFCFB;}\n      .dbox .k{font-size:11px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;color:var(--faint);}\n      .dbox .v{font-size:14.5px;font-weight:800;margin-top:3px;line-height:1.35;}\n      .fee-table{width:100%;border-collapse:collapse;font-size:13.5px;}\n      .fee-table th,.fee-table td{text-align:left;padding:8px 10px;border:1px solid var(--line);vertical-align:top;}\n      .fee-table th{background:#F7FAF7;font-weight:700;width:38%;}\n      .fine-note{font-size:12px;color:var(--faint);margin-top:8px;line-height:1.5;}\n      .mc-bar{display:flex;height:12px;border-radius:99px;overflow:hidden;background:#EDF1ED;margin:8px 0 6px;}\n      .mc-bar span{display:block;height:100%;}\n      .hold-table{width:100%;border-collapse:collapse;font-size:13px;}\n      .hold-table td{padding:6px 8px;border-bottom:1px solid var(--line);}\n      .hold-table td:last-child{text-align:right;font-weight:800;white-space:nowrap;}\n      details.monthly-det{border:1.5px solid var(--line);border-radius:12px;padding:10px 14px;margin-top:10px;background:#FBFCFB;}\n      details.monthly-det summary{cursor:pointer;font-weight:800;font-size:13.5px;padding:4px 0;}\n      .drawer-foot{border-top:1px solid var(--line);padding-top:12px;font-size:12px;color:var(--faint);line-height:1.55;}\n      .drawer-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px;}\n\n      /* Your details panel */\n      .cd-grid{display:grid;grid-template-columns:1fr;gap:16px;}\n      @media(min-width:760px){.cd-grid{grid-template-columns:repeat(3,1fr);}}\n      .cd-field label{font-size:13px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;color:var(--muted);display:block;margin-bottom:7px;}\n      .cd-input{width:100%;font-family:inherit;font-size:16px;font-weight:600;padding:13px 14px;border:1.5px solid var(--line-strong);border-radius:12px;background:#fff;color:var(--ink);outline:none;min-height:50px;}\n      .cd-input:focus{border-color:var(--primary);}\n      .cd-input.invalid{border-color:#B3261E;background:#FEF7F6;}\n      .phone-wrap{display:flex;}\n      .phone-prefix{display:grid;place-items:center;padding:0 13px;border:1.5px solid var(--line-strong);border-right:none;border-radius:12px 0 0 12px;background:#F7FAF7;font-weight:800;font-size:15px;color:var(--muted);}\n      .phone-wrap .cd-input{border-radius:0 12px 12px 0;}\n      .field-err{display:none;color:#B3261E;font-size:12.5px;font-weight:700;margin:6px 0 0;line-height:1.4;}\n      .field-err.show{display:block;animation:stepIn .25s ease both;}\n      .consent-row{display:flex;gap:11px;align-items:flex-start;margin-top:18px;font-size:14.5px;font-weight:600;line-height:1.5;cursor:pointer;}\n      .consent-row input{width:22px;height:22px;flex:none;margin:1px 0 0;accent-color:var(--primary);cursor:pointer;}\n      .consent-row.bad{color:#B3261E;}\n      .privacy-line{font-size:12.5px;color:var(--faint);line-height:1.55;margin:12px 0 0;}\n      .success-box{display:none;background:var(--primary-soft);border:1.5px solid #BFE0CF;border-radius:12px;padding:15px 16px;margin-top:16px;font-size:15px;line-height:1.55;}\n      .success-box.show{display:block;animation:stepIn .35s ease both;}\n      .success-box .small{display:block;font-size:12.5px;color:var(--muted);margin-top:5px;}\n      .panel.err-flash{box-shadow:0 0 0 4px rgba(179,38,30,.28),var(--shadow);}\n\n      /* Print report - hidden on screen */\n      #printReport{display:none;}\n      @media print{\n        @page{size:A4;margin:14mm;}\n        body{background:#fff !important;}\n        .wrap,.modal-overlay{display:none !important;}\n        #printReport{display:block !important;color:#152420;font-family:var(--font-google-sans), sans-serif;font-size:12.5px;line-height:1.5;}\n        #printReport *{box-shadow:none !important;}\n        .pr-head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #0C6B4F;padding-bottom:12px;margin-bottom:16px;}\n        .pr-brand{font-size:22px;font-weight:800;letter-spacing:-.02em;}\n        .pr-brand span{color:#0C6B4F;}\n        .pr-meta{text-align:right;font-size:11.5px;color:#5C6B63;}\n        .pr-title{font-size:18px;font-weight:800;margin:0 0 4px;}\n        .pr-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px 18px;margin:12px 0;}\n        .pr-box{border:1px solid #DEE7E0;border-radius:10px;padding:12px;}\n        .pr-box h3{margin:0 0 8px;font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:#5C6B63;}\n        .pr-table{width:100%;border-collapse:collapse;margin:10px 0 14px;font-size:12px;}\n        .pr-table th{text-align:left;background:#E7F3EC;padding:8px;border:1px solid #DEE7E0;}\n        .pr-table td{padding:8px;border:1px solid #DEE7E0;vertical-align:top;}\n        .pr-table td.r,.pr-table th.r{text-align:right;}\n        .pr-note{font-size:11px;color:#5C6B63;line-height:1.5;}\n        .pr-ai{border:1px solid #DEE7E0;border-radius:10px;padding:12px;margin-top:12px;}\n        .pr-ai h3{margin-top:0;}\n        .pr-footer{margin-top:16px;border-top:1px solid #DEE7E0;padding-top:10px;font-size:11px;color:#5C6B63;}\n      }\n      @media (prefers-reduced-motion: reduce){\n        *,*::before,*::after{animation-duration:.01ms !important;transition-duration:.01ms !important;}\n        html{scroll-behavior:auto;}\n      }";
const BODY_HTML = "<div class=\"wrap\">\n\n      <div class=\"progress-row\" aria-hidden=\"true\">\n        <span class=\"progress-label\" id=\"progressLabel\">Step 1 of 2</span>\n        <div class=\"progress-track\"><div class=\"progress-fill\" id=\"progressFill\"></div></div>\n      </div>\n\n      <!-- ================= STEP 1 ================= -->\n      <section class=\"step active\" id=\"step1\" aria-label=\"Choose your investing style\">\n        <h1>How do you want your money to grow?</h1>\n        <p class=\"sub\">Pick one style. No forms, no jargon \u2014 and you can change it anytime.</p>\n\n        <div class=\"style-grid\" id=\"styleGrid\"></div>\n\n        <div class=\"quiz-link-wrap\">\n          <button class=\"quiz-link\" id=\"quizToggle\" type=\"button\">Not sure? Answer 3 quick questions \u2192</button>\n        </div>\n\n        <div class=\"quiz-panel\" id=\"quizPanel\" aria-label=\"Quick style quiz\">\n          <div class=\"quiz-q\" data-q=\"0\">\n            <p><span>Q1.</span>If your money fell 20% in one month, you would\u2026</p>\n            <div class=\"quiz-opts\">\n              <button class=\"quiz-opt\" type=\"button\" data-score=\"1\">Take it out. Safety first</button>\n              <button class=\"quiz-opt\" type=\"button\" data-score=\"2\">Wait and watch</button>\n              <button class=\"quiz-opt\" type=\"button\" data-score=\"3\">Invest more \u2014 it's cheaper now</button>\n            </div>\n          </div>\n          <div class=\"quiz-q\" data-q=\"1\">\n            <p><span>Q2.</span>When will you need this money?</p>\n            <div class=\"quiz-opts\">\n              <button class=\"quiz-opt\" type=\"button\" data-score=\"1\">Within 3 years</button>\n              <button class=\"quiz-opt\" type=\"button\" data-score=\"2\">In 3 to 7 years</button>\n              <button class=\"quiz-opt\" type=\"button\" data-score=\"3\">After 7 years</button>\n            </div>\n          </div>\n          <div class=\"quiz-q\" data-q=\"2\">\n            <p><span>Q3.</span>Your main priority is\u2026</p>\n            <div class=\"quiz-opts\">\n              <button class=\"quiz-opt\" type=\"button\" data-score=\"1\">Protect what I have</button>\n              <button class=\"quiz-opt\" type=\"button\" data-score=\"2\">Growth with some safety</button>\n              <button class=\"quiz-opt\" type=\"button\" data-score=\"3\">Maximum growth</button>\n            </div>\n          </div>\n          <div class=\"quiz-result\" id=\"quizResult\" role=\"status\"></div>\n        </div>\n      </section>\n\n      <!-- ================= STEP 2 ================= -->\n      <section class=\"step\" id=\"step2\" aria-label=\"Your goal-based plan\">\n        <div class=\"style-banner\">\n          <span class=\"style-chip\"><span class=\"dot\" id=\"bannerDot\"></span>Your style: <span id=\"bannerStyle\">Moderate</span></span>\n          <span class=\"spacer\"></span>\n          <button class=\"btn\" id=\"changeStyleBtn\" type=\"button\">Change style</button>\n        </div>\n        <div class=\"try-row\">\n          <span>Compare instantly:</span>\n          <span id=\"stylePills\"></span>\n        </div>\n\n        <h2>What's the money for?</h2>\n        <p class=\"sub\">Tap a goal \u2014 your plan below updates instantly.</p>\n        <div class=\"goal-grid\" id=\"goalGrid\"></div>\n\n        <div class=\"guardrail\" id=\"guardrail\" role=\"note\">\n          <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;margin-top:1px\"><path d=\"M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>\n          <p id=\"guardrailText\">Short time + Aggressive is risky. A calmer style usually fits better here.</p>\n          <button class=\"btn\" id=\"guardrailBtn\" type=\"button\">Switch to Moderate</button>\n        </div>\n\n        <div class=\"panel\">\n          <h2>Your numbers</h2>\n          <p class=\"sub\">Drag the sliders \u2014 everything recalculates live.</p>\n          <div class=\"calc-grid\">\n            <div>\n              <div class=\"field\">\n                <div class=\"field-head\">\n                  <label for=\"targetRange\">Target amount</label>\n                  <span class=\"amount-input\">\u20b9<input id=\"targetInput\" type=\"text\" inputmode=\"numeric\" aria-label=\"Target amount in rupees\" /></span>\n                </div>\n                <input type=\"range\" id=\"targetRange\" min=\"0\" max=\"200\" value=\"100\" aria-label=\"Target amount slider\" />\n                <div class=\"range-marks\"><span>\u20b950,000</span><span>\u20b95 Crore</span></div>\n              </div>\n              <div class=\"field\">\n                <div class=\"field-head\">\n                  <label for=\"yearsRange\">Time you have</label>\n                  <span class=\"amount-input\"><input id=\"yearsInput\" type=\"text\" inputmode=\"numeric\" style=\"width:44px\" aria-label=\"Years\" />&nbsp;yrs</span>\n                </div>\n                <input type=\"range\" id=\"yearsRange\" min=\"1\" max=\"30\" step=\"1\" value=\"10\" aria-label=\"Years slider\" />\n                <div class=\"range-marks\"><span>1 year</span><span>30 years</span></div>\n              </div>\n              <p class=\"assumption\" id=\"assumptionText\"></p>\n            </div>\n            <div class=\"results\" aria-live=\"polite\">\n              <div class=\"sip-hero\">\n                <div class=\"k\">Monthly SIP needed</div>\n                <div class=\"v\"><span id=\"sipValue\">\u20b90</span> <small>/ month</small></div>\n              </div>\n              <div class=\"result-row\"><span class=\"k\">You invest</span><span class=\"v\" id=\"investedValue\">\u20b90</span></div>\n              <div class=\"result-row\"><span class=\"k\">Growth (market gains)</span><span class=\"v\" id=\"growthValue\">\u20b90</span></div>\n              <div class=\"result-row alt\"><span class=\"k\">Or, one-time lumpsum today</span><span class=\"v\" id=\"lumpsumValue\">\u20b90</span></div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"panel\">\n          <h2>How your money is split</h2>\n          <p class=\"sub\" id=\"allocSub\">The mix for your chosen style.</p>\n          <div class=\"alloc-grid\">\n            <div class=\"donut-wrap\">\n              <svg width=\"210\" height=\"210\" viewBox=\"0 0 210 210\" role=\"img\" aria-label=\"Allocation chart\">\n                <circle cx=\"105\" cy=\"105\" r=\"84\" fill=\"none\" stroke=\"#EDF1ED\" stroke-width=\"30\"/>\n                <circle class=\"donut-seg\" id=\"segEquity\" cx=\"105\" cy=\"105\" r=\"84\" fill=\"none\" stroke=\"#178A50\" stroke-width=\"30\"/>\n                <circle class=\"donut-seg\" id=\"segDebt\" cx=\"105\" cy=\"105\" r=\"84\" fill=\"none\" stroke=\"#2F6DB3\" stroke-width=\"30\"/>\n                <circle class=\"donut-seg\" id=\"segGold\" cx=\"105\" cy=\"105\" r=\"84\" fill=\"none\" stroke=\"#DFA00C\" stroke-width=\"30\"/>\n                <circle class=\"donut-seg\" id=\"segLiquid\" cx=\"105\" cy=\"105\" r=\"84\" fill=\"none\" stroke=\"#93A1B0\" stroke-width=\"30\"/>\n              </svg>\n              <div class=\"donut-center\">\n                <div class=\"big\" id=\"donutBig\">50%</div>\n                <div class=\"small\" id=\"donutSmall\">in Equity</div>\n              </div>\n            </div>\n            <ul class=\"legend\" id=\"allocLegend\"></ul>\n          </div>\n        </div>\n\n        <div class=\"panel\">\n          <h2>Funds from the FH Recommended List</h2>\n          <p class=\"sub\">Regular Plan \u00b7 Growth \u00b7 Picked by Fund Horizon, not a random list. Amounts update live with your SIP.</p>\n          <div id=\"fundList\"></div>\n          <p class=\"list-note\">Fund list: Fund Horizon's curated FH Recommended List (Regular Plan, Growth). Live NAV/returns are shown on the full site from AMFI feeds.</p>\n        </div>\n\n        <div class=\"panel\" id=\"pmsPanel\">\n          <h2>Add PMS? For larger portfolios</h2>\n          <p class=\"sub\">Portfolio Management Services (PMS) sit alongside Mutual Funds for larger lump sums. Choose one route \u2014 you can change it anytime.</p>\n          <div class=\"pms-strip\">PMS: \u20b950 Lakh minimum \u00b7 SEBI-registered managers only \u00b7 Returns not assured \u00b7 Read the Disclosure Document before signing.</div>\n\n          <div class=\"field\" style=\"margin-bottom:6px\">\n            <div class=\"field-head\">\n              <label for=\"corpusInput\">How much can you invest as a lump sum today?</label>\n              <span class=\"amount-input\">\u20b9<input id=\"corpusInput\" type=\"text\" inputmode=\"numeric\" aria-label=\"Lump sum corpus in rupees\" /></span>\n            </div>\n          </div>\n          <div class=\"pms-chips\" id=\"corpusChips\">\n            <button type=\"button\" class=\"pms-chip\" data-corpus=\"4000000\">Under \u20b950 Lakh</button>\n            <button type=\"button\" class=\"pms-chip\" data-corpus=\"7500000\">\u20b975 Lakh</button>\n            <button type=\"button\" class=\"pms-chip\" data-corpus=\"10000000\">\u20b91 Crore</button>\n            <button type=\"button\" class=\"pms-chip\" data-corpus=\"20000000\">\u20b92 Crore+</button>\n          </div>\n\n          <div class=\"route-grid\" id=\"routeGrid\">\n            <button type=\"button\" class=\"route-card selected\" data-route=\"mf\">\n              <span class=\"route-tick\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></span>\n              <h3>Mutual Funds only</h3>\n              <p>SIP-based, start with any amount.</p>\n            </button>\n            <button type=\"button\" class=\"route-card\" data-route=\"mix\" id=\"routeMixCard\">\n              <span class=\"route-tick\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></span>\n              <h3>Mutual Funds + PMS mix</h3>\n              <p>Part lump sum into PMS, rest stays in Mutual Funds.</p>\n            </button>\n            <button type=\"button\" class=\"route-card\" data-route=\"pms\">\n              <span class=\"route-tick\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></span>\n              <h3>PMS only \u2014 talk to us</h3>\n              <p>Enquiry only. Structure is decided after a suitability discussion.</p>\n            </button>\n          </div>\n          <div class=\"pms-note-amber\" id=\"pmsEligibilityNote\" role=\"note\"></div>\n\n          <div class=\"mix-panel\" id=\"mixPanel\">\n            <p class=\"mix-explain\">PMS takes a one-time lump sum. Your monthly SIP for your goal stays in Mutual Funds \u2014 both run side by side.</p>\n            <div class=\"mix-slider-head\"><span>Mutual Funds <span id=\"mixMfPctLabel\">70%</span></span><span>PMS <span id=\"mixPmsPctLabel\">30%</span></span></div>\n            <input type=\"range\" id=\"mixRange\" min=\"0\" max=\"100\" step=\"1\" value=\"30\" aria-label=\"PMS share of lump sum corpus\" />\n            <div class=\"range-marks\"><span>All Mutual Funds</span><span id=\"mixCapLabel\">PMS capped at 50% for this style</span><span>All PMS</span></div>\n            <div class=\"pms-note-amber\" id=\"mixStyleNote\" role=\"note\">PMS holds concentrated equity \u2014 it usually does not fit a Conservative style well.</div>\n            <div class=\"mix-outputs\">\n              <div class=\"mix-out\"><div class=\"k\">Your lump-sum corpus</div><div class=\"v\" id=\"mixCorpusVal\">\u20b90</div></div>\n              <div class=\"mix-out\"><div class=\"k\">\u2192 Mutual Funds (lump sum)</div><div class=\"v\" id=\"mixMfVal\">\u20b90</div></div>\n              <div class=\"mix-out pms-out\"><div class=\"k\">\u2192 PMS</div><div class=\"v\" id=\"mixPmsVal\">\u20b90</div></div>\n            </div>\n            <div class=\"pms-note-red\" id=\"mixValidNote\" role=\"alert\"></div>\n            <div class=\"split-wrap\" id=\"splitWrap\">\n              <div class=\"mix-slider-head\"><span id=\"splitNameA\">Strategy A 50%</span><span id=\"splitNameB\">Strategy B 50%</span></div>\n              <input type=\"range\" id=\"splitRange\" min=\"50\" max=\"50\" step=\"1\" value=\"50\" aria-label=\"Split between the two selected PMS strategies\" />\n              <div class=\"range-marks\"><span>Each manager keeps at least \u20b950 Lakh</span></div>\n            </div>\n            <h3 style=\"margin:18px 0 2px;font-size:16px\">PMS strategies for this portion \u2014 from the FH list</h3>\n            <p style=\"margin:0 0 4px;color:var(--muted);font-size:13.5px\">Tap a strategy to select it \u2014 one strategy takes the full PMS portion by default. Historical returns below are from APMI disclosures; no returns are projected for PMS. Final selection happens after a suitability discussion and the portfolio manager's risk profiling \u2014 PMS cannot be bought from a button.</p>\n            <div id=\"pmsStratList\"></div>\n            <div class=\"pms-note-amber\" id=\"secondStratNote\" role=\"note\"></div>\n            <div class=\"fund-actions\" style=\"margin-top:8px\"><button type=\"button\" class=\"link-btn secondary\" id=\"seeAllPmsBtn\">See all PMS on FH list</button></div>\n            <div class=\"see-all\" id=\"seeAllPms\">\n              <h4>All PMS on the FH list \u2014 tap to select, or open details</h4>\n              <ul id=\"seeAllPmsList\"></ul>\n            </div>\n          </div>\n\n          <div class=\"pms-only-panel\" id=\"pmsOnlyPanel\">\n            <p><strong>PMS only is an enquiry, not a calculator result.</strong> Even at 100% PMS, the \u20b950 Lakh per-manager minimum and eligibility check still apply, and the final structure is decided only after a suitability discussion and the portfolio manager's own risk profiling. Your Mutual Fund SIP plan above stays as your reference until that discussion happens.</p>\n            <button class=\"btn primary\" id=\"pmsTalkBtn\" type=\"button\">Talk to Fund Horizon</button>\n          </div>\n        </div>\n\n        <div class=\"panel\">\n          <h2>Before you invest \u2014 3 quick checks</h2>\n          <p class=\"sub\">Tap Yes or Not yet. No forms, nothing is saved.</p>\n          <div class=\"protect-grid\">\n            <div class=\"protect-card\">\n              <h3><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3l7 3v5c0 4.5-3 7.6-7 9-4-1.4-7-4.5-7-9V6l7-3z\"/></svg>Emergency money</h3>\n              <p class=\"q\">Do you have 6 months of expenses saved separately?</p>\n              <div class=\"yn\" data-check=\"emergency\">\n                <button type=\"button\" data-val=\"yes\">Yes</button>\n                <button type=\"button\" data-val=\"no\">Not yet</button>\n              </div>\n              <p class=\"gap-note\">Keep a small safety cushion aside first \u2014 it stops you breaking this plan when surprises hit.</p>\n            </div>\n            <div class=\"protect-card\">\n              <h3><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.6l-1-1a5.5 5.5 0 1 0-7.8 7.8l1 1L12 21.2l7.8-7.8 1-1a5.5 5.5 0 0 0 0-7.8z\"/></svg>Term cover</h3>\n              <p class=\"q\">If something happened to you, is your family covered?</p>\n              <div class=\"yn\" data-check=\"term\">\n                <button type=\"button\" data-val=\"yes\">Yes</button>\n                <button type=\"button\" data-val=\"no\">Not yet</button>\n              </div>\n              <p class=\"gap-note\">A simple term plan protects your family's goals \u2014 usually 10\u201315\u00d7 your yearly income.</p>\n            </div>\n            <div class=\"protect-card\">\n              <h3><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg>Health cover</h3>\n              <p class=\"q\">Do you have health insurance beyond your office policy?</p>\n              <div class=\"yn\" data-check=\"health\">\n                <button type=\"button\" data-val=\"yes\">Yes</button>\n                <button type=\"button\" data-val=\"no\">Not yet</button>\n              </div>\n              <p class=\"gap-note\">One hospital bill can break a plan. A family health policy keeps your goals safe.</p>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"panel\" id=\"detailsPanel\">\n          <h2>Your details</h2>\n          <p class=\"sub\">Needed for your PDF report and so Fund Horizon can reach you about this plan.</p>\n          <div class=\"cd-grid\">\n            <div class=\"cd-field\">\n              <label for=\"cdName\">Full name</label>\n              <input class=\"cd-input\" id=\"cdName\" type=\"text\" placeholder=\"e.g. Priya Sharma\" autocomplete=\"name\" />\n              <p class=\"field-err\" id=\"errName\">Please enter your full name (at least 3 letters).</p>\n            </div>\n            <div class=\"cd-field\">\n              <label for=\"cdEmail\">Email ID</label>\n              <input class=\"cd-input\" id=\"cdEmail\" type=\"email\" placeholder=\"you@example.com\" autocomplete=\"email\" />\n              <p class=\"field-err\" id=\"errEmail\">Please enter a valid email ID.</p>\n            </div>\n            <div class=\"cd-field\">\n              <label for=\"cdPhone\">Phone number (mobile)</label>\n              <div class=\"phone-wrap\"><span class=\"phone-prefix\">+91</span><input class=\"cd-input\" id=\"cdPhone\" type=\"tel\" inputmode=\"numeric\" placeholder=\"98XXX XXXXX\" autocomplete=\"tel\" /></div>\n              <p class=\"field-err\" id=\"errPhone\">Please enter a valid 10-digit Indian mobile number.</p>\n            </div>\n          </div>\n          <label class=\"consent-row\" id=\"consentRow\">\n            <input type=\"checkbox\" id=\"cdConsent\" />\n            <span>I agree to be contacted by Fund Horizon about my plan on phone, WhatsApp and email.</span>\n          </label>\n          <p class=\"field-err\" id=\"errConsent\">Please tick the consent box so Fund Horizon can contact you about your plan.</p>\n          <p class=\"privacy-line\">Used only to prepare your plan and for Fund Horizon to contact you. We do not sell your details. On the live site, these details go to Fund Horizon's CRM so an RM can reach you.</p>\n          <div class=\"success-box\" id=\"talkSuccess\" role=\"status\"></div>\n        </div>\n\n        <div class=\"summary-card\" id=\"summaryCard\">\n          <h2 style=\"margin:0\">Your plan at a glance</h2>\n          <div class=\"summary-grid\">\n            <div><div class=\"k\">Style</div><div class=\"v\" id=\"sumStyle\">\u2014</div></div>\n            <div><div class=\"k\">Goal</div><div class=\"v\" id=\"sumGoal\">\u2014</div></div>\n            <div><div class=\"k\">Target</div><div class=\"v\" id=\"sumTarget\">\u2014</div></div>\n            <div><div class=\"k\">Time</div><div class=\"v\" id=\"sumYears\">\u2014</div></div>\n            <div><div class=\"k\">Monthly SIP</div><div class=\"v\" id=\"sumSip\">\u2014</div></div>\n          </div>\n          <div class=\"summary-route\"><span class=\"k\">Route</span><span id=\"sumRoute\">Mutual Funds only</span></div>\n          <div class=\"summary-route\" id=\"sumPrepared\" style=\"display:none\"><span class=\"k\">Prepared for</span><span id=\"sumPreparedVal\"></span></div>\n          <div class=\"report-actions\">\n            <div class=\"action-btns\" style=\"margin-top:0\">\n              <button class=\"btn ai-btn\" id=\"explainPlanBtn\" type=\"button\">\u2726 Explain with AI</button>\n              <button class=\"btn pdf-btn\" id=\"downloadPdfBtn\" type=\"button\">Download PDF report</button>\n            </div>\n            <p style=\"font-size:12.5px;color:var(--muted);margin:10px 0 0\">Explain opens a plain-English summary of this exact plan. PDF opens your browser print view \u2014 choose \u201cSave as PDF\u201d.</p>\n          </div>\n        </div>\n\n        <div class=\"cta-row\">\n          <button class=\"btn primary\" id=\"ctaBtn\" type=\"button\">Talk to Fund Horizon</button>\n          <button class=\"btn ghost\" id=\"startOverBtn\" type=\"button\">Start over</button>\n        </div>\n\n        <div class=\"disclosures\" id=\"disclosuresBlock\">\n          <h2>Important disclosures</h2>\n          <p><strong>Mutual Funds:</strong> Mutual fund investments are subject to market risks, read all scheme related documents carefully. Past performance does not indicate future returns. Fund Horizon is an AMFI Registered Mutual Fund Distributor \u00b7 ARN 345439. The funds shown are from Fund Horizon's curated list for education and planning; this page does not constitute an investment offer or recommendation.</p>\n          <p><strong>PMS:</strong> Portfolio Management Services (PMS) are offered by SEBI-registered Portfolio Managers under the SEBI (Portfolio Managers) Regulations. The minimum investment is \u20b950 Lakh per portfolio manager. PMS portfolios are concentrated, market-linked and carry higher risk than diversified mutual funds; returns are not assured or promised and past performance does not indicate future returns. Fees, charges and taxes apply as per the agreement with the portfolio manager. Before investing, read the portfolio manager's Disclosure Document carefully, complete their risk profiling and sign the PMS agreement directly with them. Fund Horizon does not manage PMS portfolios \u2014 PMS services are provided by the respective portfolio manager.</p>\n          <p><strong>General:</strong> All return figures on this page (8% / 10.5% / 12%) are assumptions for illustration only, not a promise or guarantee. This tool is for education and planning only and is not a solicitation to buy any fund or service. Please consult your advisor and consider your own situation before investing.</p>\n        </div>\n\n        <p class=\"disclaimer\">For education only. Mutual funds are market-linked, returns are not assured. Figures use assumed returns and are illustrations, not promises.</p>\n      </section>\n\n    </div>\n\n    <!-- AI Explainer Modal -->\n    <div class=\"modal-overlay\" id=\"aiModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"aiModalTitle\">\n      <div class=\"modal-card\">\n        <div class=\"modal-head\">\n          <h3 id=\"aiModalTitle\">Educational Explanation</h3>\n          <span class=\"badge\">Rule-Based Summary</span>\n          <button class=\"modal-close\" id=\"aiModalClose\" type=\"button\" aria-label=\"Close explanation\">\u00d7</button>\n        </div>\n        <p class=\"modal-sub\" id=\"aiModalSub\">Built from your live plan numbers on this screen. On the full site this uses the AI explainer with this same summary as fallback.</p>\n        <div id=\"aiLoading\" class=\"shimmer-wrap\">\n          <p style=\"font-weight:700;margin:0 0 12px;color:var(--muted)\">Writing your explanation\u2026</p>\n          <div class=\"shimmer-line\" style=\"width:92%\"></div>\n          <div class=\"shimmer-line\" style=\"width:84%\"></div>\n          <div class=\"shimmer-line\" style=\"width:96%\"></div>\n          <div class=\"shimmer-line\" style=\"width:62%\"></div>\n        </div>\n        <div id=\"aiContent\" class=\"ai-body\" style=\"display:none\"></div>\n        <div class=\"ai-foot\" id=\"aiFoot\" style=\"display:none\">For education only. Mutual funds are market-linked, returns are not assured. Figures use assumed returns and are illustrations, not promises.<br><strong>AMFI Registered Distributor \u00b7 ARN 345439</strong> \u00b7 Fund Horizon</div>\n      </div>\n    </div>\n\n    <!-- PMS Strategy Detail Drawer -->\n    <div class=\"modal-overlay\" id=\"pmsModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"pmsModalTitle\">\n      <div class=\"modal-card pms-card\">\n        <div id=\"pmsDrawerContent\"></div>\n      </div>\n    </div>\n\n    <!-- Print-only report -->\n    <div id=\"printReport\" aria-hidden=\"true\"></div>";

